{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "PQC Upgrade Cost Analysis — Responsive KPI header: unified top card with accent stripe, three cost-breakdown tiles, and proportional composition bar. Reads pre-computed fields from tychon-pqc-system-readiness*. No cost arithmetic in Vega.",
  "autosize": { "type": "fit", "contains": "padding" },
  "padding": { "left": 16, "right": 16, "top": 16, "bottom": 16 },
  "data": [
    {
      "name": "cost_totals",
      "url": {
        "%context%": true,
        "%timefield%": "@timestamp",
        "index": "tychon-pqc-system-readiness*",
        "body": {
          "size": 0,
          "aggs": {
            "agg_labor_hours": { "sum":         { "field": "quantum_readiness.cost_analysis.total_labor_hours" } },
            "agg_total_cost":  { "sum":         { "field": "quantum_readiness.cost_analysis.total_cost_usd" } },
            "agg_labor_cost":  { "sum":         { "field": "quantum_readiness.cost_analysis.total_labor_cost_usd" } },
            "agg_hw_cost":     { "sum":         { "field": "quantum_readiness.cost_analysis.total_hardware_cost_usd" } },
            "agg_lic_cost":    { "sum":         { "field": "quantum_readiness.cost_analysis.total_license_cost_usd" } },
            "agg_asset_count": { "value_count": { "field": "quantum_readiness.cost_analysis.total_cost_usd" } }
          }
        }
      },
      "format": { "property": "aggregations" },
      "transform": [
        { "type": "formula", "as": "labor_hours", "expr": "isValid(datum.agg_labor_hours)  ? datum.agg_labor_hours.value  : 0" },
        { "type": "formula", "as": "total_cost",  "expr": "isValid(datum.agg_total_cost)   ? datum.agg_total_cost.value   : 0" },
        { "type": "formula", "as": "labor_cost",  "expr": "isValid(datum.agg_labor_cost)   ? datum.agg_labor_cost.value   : 0" },
        { "type": "formula", "as": "hw_cost",     "expr": "isValid(datum.agg_hw_cost)      ? datum.agg_hw_cost.value      : 0" },
        { "type": "formula", "as": "lic_cost",    "expr": "isValid(datum.agg_lic_cost)     ? datum.agg_lic_cost.value     : 0" },
        { "type": "formula", "as": "asset_count", "expr": "isValid(datum.agg_asset_count)  ? datum.agg_asset_count.value  : 0" }
      ]
    }
  ],
  "signals": [
    { "name": "gap",   "value": 12 },
    { "name": "topH",  "value": 124 },
    { "name": "midH",  "value": 88 },
    { "name": "midY",  "update": "topH + gap" },
    { "name": "cw",    "update": "(width - gap * 2) / 3" },
    { "name": "c2x",   "update": "cw + gap" },
    { "name": "c3x",   "update": "(cw + gap) * 2" },
    { "name": "div1x", "update": "width / 3" },
    { "name": "div2x", "update": "width * 2 / 3" },
    {
      "name": "r",
      "update": "length(data('cost_totals')) > 0 ? data('cost_totals')[0] : {total_cost:0,labor_hours:0,labor_cost:0,hw_cost:0,lic_cost:0,asset_count:0}"
    }
  ],
  "marks": [
    {
      "type": "rect",
      "encode": { "enter": {
        "x": { "value": 0 }, "y": { "value": 0 },
        "width": { "signal": "width" }, "height": { "signal": "topH" },
        "fill": { "value": "#f8faff" },
        "stroke": { "value": "#dbeafe" }, "strokeWidth": { "value": 1.5 },
        "cornerRadius": { "value": 10 }
      }}
    },
    {
      "type": "rect",
      "encode": { "enter": {
        "x": { "value": 0 }, "y": { "value": 0 },
        "width": { "signal": "width" }, "height": { "value": 4 },
        "fill": { "value": "#3b82f6" },
        "cornerRadiusTopLeft": { "value": 10 }, "cornerRadiusTopRight": { "value": 10 }
      }}
    },
    {
      "type": "rule",
      "encode": { "enter": {
        "x": { "signal": "div1x" }, "y": { "value": 18 },
        "x2": { "signal": "div1x" }, "y2": { "signal": "topH - 18" },
        "stroke": { "value": "#e2e8f0" }, "strokeWidth": { "value": 1 }
      }}
    },
    {
      "type": "rule",
      "encode": { "enter": {
        "x": { "signal": "div2x" }, "y": { "value": 18 },
        "x2": { "signal": "div2x" }, "y2": { "signal": "topH - 18" },
        "stroke": { "value": "#e2e8f0" }, "strokeWidth": { "value": 1 }
      }}
    },
    {
      "type": "text",
      "encode": { "enter": {
        "x": { "signal": "div1x / 2" }, "y": { "signal": "topH * 0.40" },
        "align": { "value": "center" }, "baseline": { "value": "middle" },
        "fontSize": { "value": 38 }, "fontWeight": { "value": "bold" },
        "fill": { "value": "#1d4ed8" },
        "text": { "signal": "'$' + format(r.total_cost, ',.0f')" }
      }}
    },
    {
      "type": "text",
      "encode": { "enter": {
        "x": { "signal": "div1x / 2" }, "y": { "signal": "topH * 0.65" },
        "align": { "value": "center" }, "baseline": { "value": "middle" },
        "fontSize": { "value": 12 }, "fill": { "value": "#64748b" },
        "text": { "value": "Total Upgrade Cost" }
      }}
    },
    {
      "type": "text",
      "encode": { "enter": {
        "x": { "signal": "div1x / 2" }, "y": { "signal": "topH * 0.85" },
        "align": { "value": "center" }, "baseline": { "value": "middle" },
        "fontSize": { "value": 10 }, "fill": { "value": "#94a3b8" },
        "text": { "signal": "r.asset_count > 0 ? '$' + format(r.total_cost / r.asset_count, ',.0f') + ' per asset' : ''" }
      }}
    },
    {
      "type": "text",
      "encode": { "enter": {
        "x": { "signal": "div1x + (div2x - div1x) / 2" }, "y": { "signal": "topH * 0.40" },
        "align": { "value": "center" }, "baseline": { "value": "middle" },
        "fontSize": { "value": 34 }, "fontWeight": { "value": "bold" },
        "fill": { "value": "#047857" },
        "text": { "signal": "format(r.labor_hours, ',.1f') + ' h'" }
      }}
    },
    {
      "type": "text",
      "encode": { "enter": {
        "x": { "signal": "div1x + (div2x - div1x) / 2" }, "y": { "signal": "topH * 0.65" },
        "align": { "value": "center" }, "baseline": { "value": "middle" },
        "fontSize": { "value": 12 }, "fill": { "value": "#64748b" },
        "text": { "value": "Total Labor Hours" }
      }}
    },
    {
      "type": "text",
      "encode": { "enter": {
        "x": { "signal": "div1x + (div2x - div1x) / 2" }, "y": { "signal": "topH * 0.85" },
        "align": { "value": "center" }, "baseline": { "value": "middle" },
        "fontSize": { "value": 10 }, "fill": { "value": "#94a3b8" },
        "text": { "signal": "r.asset_count > 0 ? format(r.labor_hours / r.asset_count, '.1f') + ' h per asset' : ''" }
      }}
    },
    {
      "type": "text",
      "encode": { "enter": {
        "x": { "signal": "div2x + (width - div2x) / 2" }, "y": { "signal": "topH * 0.40" },
        "align": { "value": "center" }, "baseline": { "value": "middle" },
        "fontSize": { "value": 34 }, "fontWeight": { "value": "bold" },
        "fill": { "value": "#7e22ce" },
        "text": { "signal": "format(r.asset_count, ',')" }
      }}
    },
    {
      "type": "text",
      "encode": { "enter": {
        "x": { "signal": "div2x + (width - div2x) / 2" }, "y": { "signal": "topH * 0.65" },
        "align": { "value": "center" }, "baseline": { "value": "middle" },
        "fontSize": { "value": 12 }, "fill": { "value": "#64748b" },
        "text": { "value": "Assets Requiring Upgrade" }
      }}
    },

    {
      "type": "rect",
      "encode": { "enter": {
        "x": { "value": 0 }, "y": { "signal": "midY" },
        "width": { "signal": "cw" }, "height": { "signal": "midH" },
        "fill": { "value": "#eff6ff" }, "stroke": { "value": "#bfdbfe" },
        "strokeWidth": { "value": 1 }, "cornerRadius": { "value": 8 }
      }}
    },
    {
      "type": "rect",
      "encode": { "enter": {
        "x": { "value": 0 }, "y": { "signal": "midY" },
        "width": { "value": 5 }, "height": { "signal": "midH" },
        "fill": { "value": "#3b82f6" },
        "cornerRadiusTopLeft": { "value": 8 }, "cornerRadiusBottomLeft": { "value": 8 }
      }}
    },
    {
      "type": "text",
      "encode": { "enter": {
        "x": { "signal": "cw / 2" }, "y": { "signal": "midY + midH * 0.34" },
        "align": { "value": "center" }, "baseline": { "value": "middle" },
        "fontSize": { "value": 26 }, "fontWeight": { "value": "bold" },
        "fill": { "value": "#1d4ed8" },
        "text": { "signal": "'$' + format(r.labor_cost, ',.0f')" }
      }}
    },
    {
      "type": "text",
      "encode": { "enter": {
        "x": { "signal": "cw / 2" }, "y": { "signal": "midY + midH * 0.58" },
        "align": { "value": "center" }, "baseline": { "value": "middle" },
        "fontSize": { "value": 11 }, "fill": { "value": "#374151" },
        "text": { "value": "Labor Cost" }
      }}
    },
    {
      "type": "text",
      "encode": { "enter": {
        "x": { "signal": "cw / 2" }, "y": { "signal": "midY + midH * 0.78" },
        "align": { "value": "center" }, "baseline": { "value": "middle" },
        "fontSize": { "value": 10 }, "fill": { "value": "#9ca3af" },
        "text": { "signal": "r.total_cost > 0 ? format(r.labor_cost / r.total_cost * 100, '.0f') + '% of total' : ''" }
      }}
    },

    {
      "type": "rect",
      "encode": { "enter": {
        "x": { "signal": "c2x" }, "y": { "signal": "midY" },
        "width": { "signal": "cw" }, "height": { "signal": "midH" },
        "fill": { "value": "#fff1f2" }, "stroke": { "value": "#fca5a5" },
        "strokeWidth": { "value": 1 }, "cornerRadius": { "value": 8 }
      }}
    },
    {
      "type": "rect",
      "encode": { "enter": {
        "x": { "signal": "c2x" }, "y": { "signal": "midY" },
        "width": { "value": 5 }, "height": { "signal": "midH" },
        "fill": { "value": "#ef4444" },
        "cornerRadiusTopLeft": { "value": 8 }, "cornerRadiusBottomLeft": { "value": 8 }
      }}
    },
    {
      "type": "text",
      "encode": { "enter": {
        "x": { "signal": "c2x + cw / 2" }, "y": { "signal": "midY + midH * 0.34" },
        "align": { "value": "center" }, "baseline": { "value": "middle" },
        "fontSize": { "value": 26 }, "fontWeight": { "value": "bold" },
        "fill": { "value": "#b91c1c" },
        "text": { "signal": "'$' + format(r.hw_cost, ',.0f')" }
      }}
    },
    {
      "type": "text",
      "encode": { "enter": {
        "x": { "signal": "c2x + cw / 2" }, "y": { "signal": "midY + midH * 0.58" },
        "align": { "value": "center" }, "baseline": { "value": "middle" },
        "fontSize": { "value": 11 }, "fill": { "value": "#374151" },
        "text": { "value": "Hardware Cost" }
      }}
    },
    {
      "type": "text",
      "encode": { "enter": {
        "x": { "signal": "c2x + cw / 2" }, "y": { "signal": "midY + midH * 0.78" },
        "align": { "value": "center" }, "baseline": { "value": "middle" },
        "fontSize": { "value": 10 }, "fill": { "value": "#9ca3af" },
        "text": { "signal": "r.total_cost > 0 ? format(r.hw_cost / r.total_cost * 100, '.0f') + '% of total' : ''" }
      }}
    },

    {
      "type": "rect",
      "encode": { "enter": {
        "x": { "signal": "c3x" }, "y": { "signal": "midY" },
        "width": { "signal": "cw" }, "height": { "signal": "midH" },
        "fill": { "value": "#fffbeb" }, "stroke": { "value": "#fcd34d" },
        "strokeWidth": { "value": 1 }, "cornerRadius": { "value": 8 }
      }}
    },
    {
      "type": "rect",
      "encode": { "enter": {
        "x": { "signal": "c3x" }, "y": { "signal": "midY" },
        "width": { "value": 5 }, "height": { "signal": "midH" },
        "fill": { "value": "#f59e0b" },
        "cornerRadiusTopLeft": { "value": 8 }, "cornerRadiusBottomLeft": { "value": 8 }
      }}
    },
    {
      "type": "text",
      "encode": { "enter": {
        "x": { "signal": "c3x + cw / 2" }, "y": { "signal": "midY + midH * 0.34" },
        "align": { "value": "center" }, "baseline": { "value": "middle" },
        "fontSize": { "value": 26 }, "fontWeight": { "value": "bold" },
        "fill": { "value": "#b45309" },
        "text": { "signal": "'$' + format(r.lic_cost, ',.0f')" }
      }}
    },
    {
      "type": "text",
      "encode": { "enter": {
        "x": { "signal": "c3x + cw / 2" }, "y": { "signal": "midY + midH * 0.58" },
        "align": { "value": "center" }, "baseline": { "value": "middle" },
        "fontSize": { "value": 11 }, "fill": { "value": "#374151" },
        "text": { "value": "License / Software Cost" }
      }}
    },
    {
      "type": "text",
      "encode": { "enter": {
        "x": { "signal": "c3x + cw / 2" }, "y": { "signal": "midY + midH * 0.78" },
        "align": { "value": "center" }, "baseline": { "value": "middle" },
        "fontSize": { "value": 10 }, "fill": { "value": "#9ca3af" },
        "text": { "signal": "r.total_cost > 0 ? format(r.lic_cost / r.total_cost * 100, '.0f') + '% of total' : ''" }
      }}
    }
  ]
}

{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "PQC Upgrade Cost — OS Category cost estimates ranked list. Reads pre-computed total_cost_usd per OS category from tychon-pqc-system-readiness*. Styled to match the main OS breakdown panel. No cost arithmetic in Vega.",
  "padding": {"top": 0, "bottom": 0, "left": 0, "right": 0},
  "background": "#111111",
  "signals": [
    {
      "name": "sel",
      "value": null,
      "on": [{
        "events": {"type": "click", "markname": "bg"},
        "update": "datum.os_category === sel ? null : datum.os_category",
        "force": true
      }]
    },
    {
      "name": "_kf",
      "value": null,
      "on": [{
        "events": {"type": "click", "markname": "bg"},
        "update": "datum.os_category === sel ? kibanaRemoveFilter({'match_phrase': {'quantum_readiness.cost_analysis.os_category': datum.os_category}}) : kibanaAddFilter({'match_phrase': {'quantum_readiness.cost_analysis.os_category': datum.os_category}})",
        "force": true
      }]
    }
  ],
  "data": [
    {
      "name": "os_costs",
      "url": {
        "%context%": true,
        "%timefield%": "@timestamp",
        "index": "tychon-pqc-system-readiness*",
        "body": {
          "size": 0,
          "aggs": {
            "qa_only": {
              "filter": { "term": { "event.dataset": "quantum_assessment" } },
              "aggs": {
                "categories": {
                  "terms": {
                    "field": "quantum_readiness.cost_analysis.os_category",
                    "size": 30,
                    "order": { "cost_sum": "desc" }
                  },
                  "aggs": {
                    "cost_sum":    { "sum": { "field": "quantum_readiness.cost_analysis.os_total_cost_usd" } },
                    "hours_sum":   { "sum": { "field": "quantum_readiness.cost_analysis.os_labor_hours" } },
                    "license_sum": { "sum": { "field": "quantum_readiness.cost_analysis.os_license_cost_usd" } },
                    "hw_sum":      { "sum": { "field": "quantum_readiness.cost_analysis.os_hardware_cost_usd" } },
                    "tier_terms":  { "terms": { "field": "quantum_readiness.cost_analysis.os_tier", "size": 1 } }
                  }
                }
              }
            }
          }
        }
      },
      "format": { "property": "aggregations" },
      "transform": [
        {
          "type": "formula", "as": "buckets",
          "expr": "isValid(datum.qa_only) && isValid(datum.qa_only.categories) ? datum.qa_only.categories.buckets : []"
        },
        { "type": "flatten", "fields": ["buckets"], "as": ["item"] },
        { "type": "filter",  "expr": "isValid(datum.item) && isValid(datum.item.key)" },
        { "type": "formula", "as": "os_category",  "expr": "datum.item.key" },
        { "type": "formula", "as": "total_cost",   "expr": "isValid(datum.item.cost_sum)    ? datum.item.cost_sum.value    : 0" },
        { "type": "formula", "as": "labor_hours",  "expr": "isValid(datum.item.hours_sum)   ? datum.item.hours_sum.value   : 0" },
        { "type": "formula", "as": "license_cost", "expr": "isValid(datum.item.license_sum) ? datum.item.license_sum.value : 0" },
        { "type": "formula", "as": "hw_cost",      "expr": "isValid(datum.item.hw_sum)      ? datum.item.hw_sum.value      : 0" },
        {
          "type": "formula", "as": "tier",
          "expr": "isValid(datum.item.tier_terms) && datum.item.tier_terms.buckets.length > 0 ? datum.item.tier_terms.buckets[0].key : 'CLASSICAL'"
        },
        {
          "type": "formula", "as": "clr",
          "expr": "datum.total_cost === 0 ? '#66bb6a' : datum.tier === 'LEGACY' ? '#ef5350' : datum.tier === 'CLASSICAL' ? '#ffa726' : '#448aff'"
        },
        {
          "type": "formula", "as": "bgclr",
          "expr": "datum.total_cost === 0 ? '#66bb6a18' : datum.tier === 'LEGACY' ? '#ef535018' : datum.tier === 'CLASSICAL' ? '#ffa72618' : '#448aff18'"
        }
      ]
    },
    {
      "name": "mx",
      "source": "os_costs",
      "transform": [
        { "type": "aggregate", "ops": ["max"], "fields": ["total_cost"], "as": ["v"] }
      ]
    }
  ],
  "scales": [
    {
      "name": "yscale",
      "type": "band",
      "domain": { "data": "os_costs", "field": "os_category", "sort": false },
      "range": { "step": 72 },
      "paddingInner": 0,
      "paddingOuter": 0
    }
  ],
  "marks": [
    {
      "type": "text",
      "encode": {"enter": {
        "x": {"value": 16}, "y": {"value": 18},
        "text": {"value": "OS UPGRADE COST ESTIMATE"},
        "fill": {"value": "#cccccc"}, "fontSize": {"value": 10}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "letterSpacing": {"value": 1.5}
      }}
    },
    {
      "type": "text",
      "encode": {"enter": {
        "x": {"value": 16}, "y": {"value": 38},
        "text": {"value": "TOTAL COST BY OS CATEGORY  —  sorted by cost desc"},
        "fill": {"value": "#555555"}, "fontSize": {"value": 9},
        "font": {"value": "monospace"}, "letterSpacing": {"value": 1}
      }}
    },
    {
      "type": "rule",
      "encode": {"enter": {
        "x": {"value": 0}, "x2": {"signal": "width"}, "y": {"value": 48},
        "stroke": {"value": "#252525"}, "strokeWidth": {"value": 1}
      }}
    },
    {
      "type": "rect",
      "name": "bg",
      "from": {"data": "os_costs"},
      "encode": {"update": {
        "x": {"value": 0}, "y": {"scale": "yscale", "field": "os_category", "offset": 48},
        "width": {"signal": "width"}, "height": {"value": 66},
        "fill": {"signal": "datum.os_category === sel ? '#1c1c2e' : datum.total_cost === 0 ? '#121a12' : '#161622'"},
        "cursor": {"value": "pointer"}
      }}
    },
    {
      "type": "rect",
      "from": {"data": "os_costs"},
      "encode": {"update": {
        "x": {"value": 0}, "y": {"scale": "yscale", "field": "os_category", "offset": 48},
        "width": {"value": 4}, "height": {"value": 66},
        "fill": {"field": "clr"}
      }}
    },
    {
      "type": "rect",
      "from": {"data": "os_costs"},
      "encode": {"update": {
        "x": {"value": 4}, "y": {"scale": "yscale", "field": "os_category", "offset": 110},
        "width": {"signal": "length(data('mx')) > 0 && data('mx')[0].v > 0 ? max((datum.total_cost / data('mx')[0].v) * (width - 4), 0) : 0"},
        "height": {"value": 4},
        "fill": {"field": "clr"},
        "opacity": {"value": 0.35}
      }}
    },
    {
      "type": "rule",
      "from": {"data": "os_costs"},
      "encode": {"update": {
        "x": {"value": 0}, "x2": {"signal": "width"},
        "y": {"scale": "yscale", "field": "os_category", "offset": 113},
        "stroke": {"value": "#222222"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "os_costs"},
      "encode": {"update": {
        "x": {"value": 18}, "y": {"scale": "yscale", "field": "os_category", "offset": 72},
        "text": {"field": "os_category"},
        "limit": {"signal": "width * 0.58 - 18"},
        "fill": {"value": "#e8e8e8"},
        "fontSize": {"value": 13}, "fontWeight": {"value": "bold"}, "font": {"value": "monospace"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "os_costs"},
      "encode": {"update": {
        "x": {"value": 18}, "y": {"scale": "yscale", "field": "os_category", "offset": 92},
        "text": {"signal": "format(datum.labor_hours, ',.1f') + ' labor hrs  |  $' + format(datum.license_cost, ',.0f') + ' license  |  $' + format(datum.hw_cost, ',.0f') + ' hardware'"},
        "limit": {"signal": "width * 0.58 - 18"},
        "fill": {"value": "#555555"}, "fontSize": {"value": 10}, "font": {"value": "monospace"}
      }}
    },
    {
      "type": "rect",
      "from": {"data": "os_costs"},
      "encode": {"update": {
        "x": {"signal": "width * 0.62"}, "y": {"scale": "yscale", "field": "os_category", "offset": 56},
        "width": {"value": 82}, "height": {"value": 17}, "cornerRadius": {"value": 2},
        "fill": {"field": "bgclr"},
        "stroke": {"field": "clr"}, "strokeWidth": {"value": 1}
      }}
    },
    {
      "type": "text",
