{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "PQC Priority Matrix — Tier x App Family heatmap. Responsive, compact layout.",
  "autosize": { "type": "fit", "contains": "padding" },
  "padding": { "left": 92, "right": 16, "top": 34, "bottom": 46 },
  "background": "#111111",

  "signals": [
    { "name": "topN", "value": 10 },
    { "name": "showCellText", "update": "bandwidth('yscale') >= 18 && bandwidth('xscale') >= 64" }
  ],

  "data": [
    {
      "name": "matrix_raw",
      "url": {
        "%context%": true,
        "%timefield%": "@timestamp",
        "index": "tychon-pqc-system-readiness*",
        "body": {
          "size": 0,
          "aggs": {
            "app_only": {
              "filter": { "term": { "event.dataset": "quantum_assessment.app_group" } },
              "aggs": {
                "families": {
                  "terms": {
                    "field": "quantum_readiness.cost_analysis.app_family",
                    "size": 40
                  },
                  "aggs": {
                    "tiers": {
                      "terms": {
                        "field": "quantum_readiness.cost_analysis.tier",
                        "size": 5
                      },
                      "aggs": {
                        "cost_sum": {
                          "sum": { "field": "quantum_readiness.cost_analysis.total_cost_usd" }
                        },
                        "instances_sum": {
                          "sum": { "field": "quantum_readiness.cost_analysis.instance_count" }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      },
      "format": { "property": "aggregations.app_only.families.buckets" },
      "transform": [
        { "type": "filter", "expr": "datum && datum.key && datum.tiers && datum.tiers.buckets" },
        { "type": "formula", "as": "app_family", "expr": "datum.key" },
        { "type": "flatten", "fields": ["tiers.buckets"], "as": ["tier_bucket"] },
        { "type": "filter", "expr": "datum.tier_bucket && datum.tier_bucket.key" },
        { "type": "formula", "as": "tier", "expr": "datum.tier_bucket.key" },
        { "type": "formula", "as": "cost", "expr": "isValid(datum.tier_bucket.cost_sum) ? datum.tier_bucket.cost_sum.value : 0" },
        { "type": "formula", "as": "instances", "expr": "isValid(datum.tier_bucket.instances_sum) ? datum.tier_bucket.instances_sum.value : 0" },
        { "type": "filter", "expr": "isFinite(datum.cost) && datum.cost >= 0" }
      ]
    },

    {
      "name": "family_order",
      "source": "matrix_raw",
      "transform": [
        { "type": "aggregate", "groupby": ["app_family"], "ops": ["sum"], "fields": ["cost"], "as": ["family_total_cost"] },
        { "type": "collect", "sort": { "field": "family_total_cost", "order": "descending" } },
        { "type": "window", "ops": ["row_number"], "as": ["rank"] },
        { "type": "filter", "expr": "datum.rank <= topN" },
        {
          "type": "formula",
