      "name": "matrix",
      "source": "matrix_raw",
      "transform": [
        {
          "type": "lookup",
          "from": "family_order",
          "key": "app_family",
          "fields": ["app_family"],
          "values": ["rank", "app_family_short", "family_total_cost"],
          "as": ["rank", "app_family_short", "family_total_cost"]
