    {
      "name": "xscale",
      "type": "band",
      "domain": ["LEGACY", "CLASSICAL"],
      "range": "width",
      "paddingInner": 0.08,
      "paddingOuter": 0.03
    },
    {
      "name": "yscale",
      "type": "band",
      "domain": { "data": "family_order", "field": "app_family_short" },
      "range": "height",
      "paddingInner": 0.08,
      "paddingOuter": 0.03
    },
    {
      "name": "cscale",
      "type": "linear",
      "domain": { "data": "matrix", "field": "cost" },
      "range": ["#1f2937", "#2563eb", "#7c3aed", "#dc2626"],
      "nice": true,
      "zero": true
    }
  ],

  "axes": [
    {
      "orient": "bottom",
      "scale": "xscale",
      "title": "Tier",
      "titleColor": "#d1d5db",
      "labelColor": "#d1d5db",
      "tickColor": "#333333",
      "domainColor": "#333333"
    },
    {
      "orient": "left",
      "scale": "yscale",
      "title": "",
      "labelColor": "#d1d5db",
      "labelLimit": 86,
      "tickColor": "#333333",
      "domainColor": "#333333"
    }
  ],

  "legends": [
    {
      "fill": "cscale",
      "title": "Cost",
      "orient": "right",
      "titleColor": "#d1d5db",
      "labelColor": "#9ca3af",
      "format": "$,.2s"
    }
  ],

  "marks": [
    {
      "type": "text",
      "encode": {
        "enter": {
          "x": { "value": 0 },
          "y": { "value": -12 },
          "text": { "value": "PRIORITY MATRIX (TOP APP FAMILIES)" },
          "fill": { "value": "#d1d5db" },
          "font": { "value": "monospace" },
          "fontSize": { "value": 10 },
          "fontWeight": { "value": "bold" },
          "letterSpacing": { "value": 0.8 }
        }
      }
    },

    {
      "type": "rect",
      "from": { "data": "matrix" },
      "encode": {
        "enter": {
          "x": { "scale": "xscale", "field": "tier" },
          "y": { "scale": "yscale", "field": "app_family_short" },
          "width": { "scale": "xscale", "band": 1 },
          "height": { "scale": "yscale", "band": 1 },
          "fill": { "scale": "cscale", "field": "cost" },
          "stroke": { "value": "#1a1a1a" },
          "strokeWidth": { "value": 1 },
          "tooltip": {
            "signal": "{'App Family': datum.app_family, 'Tier': datum.tier, 'Total Cost': '$' + format(datum.cost, ',.0f'), 'Instances': format(datum.instances, ',.0f')}"
          }
        }
      }
    },

    {
      "type": "text",
      "from": { "data": "matrix" },
      "encode": {
        "enter": {
          "x": { "scale": "xscale", "field": "tier", "band": 0.5 },
          "y": { "scale": "yscale", "field": "app_family_short", "band": 0.5 },
          "align": { "value": "center" },
          "baseline": { "value": "middle" },
          "fontSize": { "value": 9 },
          "fontWeight": { "value": "bold" },
          "fill": { "value": "#f9fafb" },
          "text": { "signal": "showCellText && datum.instances > 0 ? format(datum.instances, ',.0f') : ''" }
        }
      }
    }
  ]
}
